INSERT INTO `panel_config_snapshots` VALUES (1, 1, 'Config.properties', 'server.local=false\nserver.test=false\nserver.daoautoupdater=false\nserver.sv=1\nserver.name=NGOC RONG\n# IP quảng bá cho client; chạy `./nro.sh lan` để tự cập nhật thành IP Wi-Fi Android\nserver.ip=127.0.0.1\n# Địa chỉ bind socket: 0.0.0.0 = nghe trên mọi interface LAN\nserver.listen.host=0.0.0.0\nserver.port=14445\nserver.sv1=NRO LOCAL:127.0.0.1:14445:0,0,0\nserver.waitlogin=0\nserver.maxperip=3\nserver.maxplayer=1000\nserver.expserver=3\n\n# DATABASE - Cấu hình thông tin kết nối MySQL/MariaDB của bạn\ndatabase.driver=org.mariadb.jdbc.Driver\ndatabase.host=127.0.0.1\ndatabase.port=3306\ndatabase.name=ngocrong\ndatabase.user=root\ndatabase.pass=\ndatabase.min=5\ndatabase.max=20\ndatabase.lifetime=1800000\n\n# PANEL AGENT\npanel.agent.enabled=true\npanel.agent.host=127.0.0.1\npanel.agent.port=14446\npanel.agent.key=change-me-in-production\n', 1, '2026-09-10 23:10:32');
