INSERT INTO `panel_event_npcs` VALUES (3, 5, 5, 400, 400, 'Vua Hùng', 0, 'template', 52, NULL, -1, -1, -1, 349, 349, 'Các con đã chuẩn bị lễ vật dâng lên Vua Hùng chưa?', 'Hãy dâng Bánh Chưng và Bánh Giầy để nhận thưởng cao quý.', '[\"Dâng bánh nhận phúc lộc!\",\"Ai nấu bánh chưng ngon nhất?\"]', 15, '[{\"title\":\"Dâng Bánh Chưng\",\"action\":{\"type\":\"open_recipe\"},\"condition\":{\"minPower\":0}},{\"title\":\"Phúc lành Vua Hùng\",\"action\":{\"type\":\"dialog\",\"message\":\"Vua Hùng ban phúc: Tăng 20% EXP trong mùa lễ hội!\"},\"condition\":{\"minPower\":0}}]', 0, '2026-09-13 12:43:16', '2026-09-13 12:43:16');
INSERT INTO `panel_event_npcs` VALUES (4, 5, 5, 440, 400, 'Nồi Bánh Chưng', 0, 'template', 53, NULL, -1, -1, -1, 349, 349, 'Nồi bánh chưng đang sôi sùng sục!', 'Bỏ nguyên liệu gạo nếp và thịt vào để nấu bánh nhé.', '[\"Bánh chưng thơm phức!\",\"Sắp chín rồi các bạn ơi!\"]', 15, '[{\"title\":\"Nấu Bánh Chưng\",\"action\":{\"type\":\"open_recipe\"},\"condition\":{\"minPower\":0}}]', 1, '2026-09-13 12:43:16', '2026-09-13 12:43:16');
INSERT INTO `panel_event_npcs` VALUES (5, 4, 5, 420, 400, 'Bí Ngô Ma Quái', 0, 'icon', 38, NULL, -1, -1, -1, 8243, 8243, 'Cho kẹo hay bị ghẹo?! Mau đưa kẹo Halloween cho ta!', 'Đổi kẹo lấy Viên Capsule kì bí chứa nhiều cải trang ma quái.', '[\"Cho kẹo hay bị ghẹo?!\",\"Bí Ngô Ma Quái xuất hiện!\"]', 12, '[{\"title\":\"Đổi Kẹo lấy Capsule Kì Bí\",\"action\":{\"type\":\"open_recipe\"},\"condition\":{\"minPower\":0}}]', 0, '2026-09-13 12:43:16', '2026-09-13 12:43:16');
INSERT INTO `panel_event_npcs` VALUES (6, 3, 5, 440, 400, 'Ông Già Noel', 0, 'icon', 38, NULL, -1, -1, -1, 4432, 4432, 'Merry Christmas! Ta mang quà Giáng Sinh đến cho các chiến binh chăm chỉ đây!', 'Thu thập Kẹo Giáng Sinh để đổi Hộp Quà Noel nhé!', '[\"Merry Christmas!\",\"Quà giáng sinh ấm áp đây!\"]', 12, '[{\"title\":\"Đổi Hộp Quà Giáng Sinh\",\"action\":{\"type\":\"open_recipe\"},\"condition\":{\"minPower\":0}}]', 0, '2026-09-13 12:43:16', '2026-09-13 12:43:16');
INSERT INTO `panel_event_npcs` VALUES (7, 1, 0, 850, 432, 'Thần Tài Đón Xuân', 0, 'template', 49, NULL, -1, -1, -1, 2987, 2987, 'Chúc mừng năm mới! An khang thịnh vượng, vạn sự như ý!', 'Hãy mang Bao Lì Xì đến để đổi Hộp Quà Tết may mắn đầu năm.', '[\"Cung chúc tân xuân!\",\"Nhận lì xì may mắn đầu năm nào!\"]', 12, '[{\"title\":\"Đổi Hộp Quà Tết\",\"action\":{\"type\":\"open_recipe\"},\"condition\":{\"minPower\":0}},{\"title\":\"Nhận Lì Xì Đầu Năm\",\"action\":{\"type\":\"dialog\",\"message\":\"Thần Tài chúc bạn năm mới phát tài phát lộc!\"},\"condition\":{\"minPower\":0}}]', 0, '2026-09-13 12:43:16', '2026-09-13 12:43:16');
INSERT INTO `panel_event_npcs` VALUES (8, 8, 5, 480, 400, 'Xe Phở Anh Hai', 0, 'template', 56, NULL, -1, -1, -1, 349, 349, 'Phở Anh Hai nóng hổi thơm ngon gia truyền đây! Nước mía mát lạnh giải khát!', 'Ăn một bát phở phục hồi 100% sinh lực và tăng sức chiến đấu!', '[\"Phở bò nóng hổi thơm ngon!\",\"Nước mía giải nhiệt mát lạnh đây!\"]', 10, '[{\"title\":\"Ăn Bát Phở Bò (50k Vàng)\",\"action\":{\"type\":\"dialog\",\"message\":\"Bạn đã ăn một bát phở bò nóng hổi, sinh lực dồi dào!\"},\"condition\":{\"minPower\":0}},{\"title\":\"Uống Ly Nước Mía (10k Vàng)\",\"action\":{\"type\":\"dialog\",\"message\":\"Nước mía ngọt mát, đã khát tức thì!\"},\"condition\":{\"minPower\":0}}]', 0, '2026-09-13 12:43:16', '2026-09-13 12:43:16');
INSERT INTO `panel_event_npcs` VALUES (9, 2, 5, 460, 400, 'Cô Bé Bán Hoa', 0, 'icon', 38, NULL, -1, -1, -1, 942, 942, 'Chào bạn! Ngày 8/3 bạn đã chuẩn bị hoa tặng phái đẹp chưa?', 'Hãy mang Bông Hoa Hồng đến đây để đổi Hộp Quà Tri Ân nhé!', '[\"Chúc mừng ngày 8/3!\",\"Hoa hồng tươi thắm mừng ngày Quốc Tế Phụ Nữ!\"]', 12, '[{\"title\":\"Đổi Hộp Quà 8/3\",\"action\":{\"type\":\"open_recipe\"},\"condition\":{\"minPower\":0}}]', 0, '2026-09-13 12:43:16', '2026-09-13 12:43:16');
INSERT INTO `panel_event_npcs` VALUES (28, 6, 5, 340, 288, 'Thỏ đại ca', 0, 'costume', -1, 463, 403, 404, 405, 4118, 4118, 'Chào mừng bạn đến với sự kiện!', 'Hãy mang đủ nguyên liệu đến gặp ta để đổi quà nhé!', '[\"Sự kiện đang diễn ra cực hot!\",\"Đến đây đổi quà ngay nào!\"]', 15, '[{\"title\":\"Top Sự Kiện\",\"action\":{\"type\":\"ranking\"},\"condition\":{\"minPower\":0,\"minLevel\":0}},{\"title\":\"shop quy đổi\",\"action\":{\"type\":\"submenu\",\"message\":\"Hãy chọn món ngươi muốn đổi:\"},\"condition\":{\"minPower\":0,\"minLevel\":0,\"requireClan\":false},\"children\":[{\"title\":\"Cửa Hàng Shop #1\",\"action\":{\"type\":\"open_shop\",\"tagName\":\"TRUNG_THU\"},\"condition\":{\"minPower\":0,\"minLevel\":0,\"requireClan\":false}}]}]', 0, '2026-09-13 14:49:42', '2026-09-13 14:49:42');
