INSERT INTO `panel_server_launches` VALUES (1, 1, 'VŨ TRỤ 15', 'KHAI MỞ VŨ TRỤ 15', 'Chào mừng các cư dân đến với máy chủ VŨ TRỤ 15. Khai mở lúc 10h00 ngày 28/08/2026 với chuỗi sự kiện Đua Top, quà NPC Chi Chi, nạp đầu và các quy tắc máy chủ độc quyền.', '2026-08-28 10:00:00', '2026-09-07 23:00:00', '2026-10-31 23:59:59', 'paused', 0, 1, '{\"npc_id\":81,\"npc_name\":\"Chi Chi\",\"gift_name\":\"Ván Bay MT (Vĩnh Viễn)\",\"item_template_id\":457,\"duration_days\":null,\"expires_at\":\"2026-10-31 23:59:59\",\"description\":\"Tặng Ván Bay MT vĩnh viễn tại NPC Chi Chi (đến hết ngày 31/10/2026)\"}', 1, '{\"title\":\"Khuyến Mãi Nạp Đầu Máy Chủ Mới\",\"description\":\"Nạp lần đầu bất kỳ nhận trọn bộ quà khủng\",\"items\":[{\"name\":\"Cờ Thùng Rác\",\"duration\":\"Vĩnh Viễn\",\"days\":null,\"desc\":\"Cờ Thùng Rác Vĩnh Viễn mang lại phong cách cực ngầu\"},{\"name\":\"Cải trang Pan Vip\",\"duration\":\"30 ngày\",\"days\":30,\"desc\":\"Tăng toàn diện chỉ số HP, KI, Sức Đánh\"},{\"name\":\"Pet Xên Hoàn Hảo\",\"duration\":\"30 ngày\",\"days\":30,\"desc\":\"Tăng 25,000 Sức Đánh cực khủng (30 ngày)\"}]}', 1, '{\"ends_at\":\"2026-09-07 23:00:00\",\"categories\":{\"mission\":{\"id\":\"mission\",\"name\":\"TOP NHIỆM VỤ\",\"description\":\"Đua Top hoàn thành các nhiệm vụ chính tuyến trong game\",\"tiers\":[{\"rank\":\"TOP 1\",\"rank_min\":1,\"rank_max\":1,\"rewards\":\"5 Capsule 1 món kích hoạt, Cải Trang CT Broly SSJ4 vĩnh viễn, 5.000 Hồng Ngọc, Ra Đa Ngọc Rồng Vip 100, Giáp Luyện Tập Cấp 5\"},{\"rank\":\"TOP 2\",\"rank_min\":2,\"rank_max\":2,\"rewards\":\"4 Capsule 1 món kích hoạt, Cải Trang CT Broly SSJ4 vĩnh viễn, 4.000 Hồng Ngọc, Ra Đa Ngọc Rồng Vip 70\"},{\"rank\":\"TOP 3\",\"rank_min\":3,\"rank_max\":3,\"rewards\":\"3 Capsule 1 món kích hoạt, Cải Trang CT Broly SSJ4 vĩnh viễn, 3.000 Hồng Ngọc, Ra Đa Ngọc Rồng Vip 50\"},{\"rank\":\"TOP 4–5\",\"rank_min\":4,\"rank_max\":5,\"rewards\":\"2 Capsule 1 món kích hoạt, Cải Trang CT Broly SSJ4 vĩnh viễn, 2.000 Hồng Ngọc, Ra Đa Ngọc Rồng Vi