INSERT INTO `radar` VALUES (1791, 14247, 5, 20, 1, -1, '[{\"head\":1727, \"body\":1728, \"leg\":1729, \"bag\":-1}]', 'Thẻ Oozaru', 'Oorazu là một sinh vật khổng lồ, đó chính là hình dáng của người xayda khi họ nhìn thấy trăng tròn và biến đổi', '[{\"id\": 101, \"param\": 10, \"activeCard\": 0}, \n{\"id\": 101, \"param\": 15, \"activeCard\": 1}, \n\n{\"id\": 101, \"param\": 20, \"activeCard\": 2}]', -1, 0, 2);
